import React from 'react';
import { Link } from 'react-router-dom';
import { excursions } from '../../Data/excursions';
import ExcursionCard from '../../components/Card/ExcursionCard';
import './FavoritesPage.css';

const FavoritesPage = ({ favoriteIds, onToggleFavorite }) => {
  const favoriteExcursions = excursions.filter(exc =>
    favoriteIds.includes(exc.id)
  );

  return (
    <div className="favorites-page">
      <div className="favorites-container">
        <h1 className="favorites-title">Избранное</h1>

        {favoriteExcursions.length === 0 ? (
          <div className="favorites-empty">
            <img
              src="/assets/icons/heart2.svg"
              alt="Пусто"
              className="empty-icon"
            />
            <h2>В избранном пока пусто</h2>
            <p>Добавляйте экскурсии, нажимая на сердечко</p>
            <Link to="/catalog" className="browse-button">
              Перейти в каталог
            </Link>
          </div>
        ) : (
          <div className="favorites-grid">
            {favoriteExcursions.map(excursion => (
              <ExcursionCard
                key={excursion.id}
                excursion={excursion}
                isFavorite={true}
                onToggleFavorite={onToggleFavorite}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default FavoritesPage;
